from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

def _ledger(revision_priority, tax_base):
    def rounded(numerator, mode):
        if mode == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    def solve(data):
        chosen = {}
        cutoff = data.get("cutoff", 10**9)
        for pos, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(pos))
            if revision_priority == "sequence_first":
                key = (sequence, event.get("revision", 0), pos)
            else:
                key = (event.get("revision", 0), pos)
            if event_id not in chosen or key > chosen[event_id][0]:
                chosen[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), data["rounding"])
            base = net if tax_base == "discounted" else raw
            tax = rounded(base * event.get("tax_bp", 0), data["rounding"])
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_component_06():
    from itertools import product

    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        options = []
        for name in names:
            versions = [row["version"] for row in packages[name]]
            options.append(sorted(versions, reverse=True) + [-1])

        def valid(assignment):
            selected = {name: version for name, version in zip(names, assignment)
                        if version != -1}
            for name, version in selected.items():
                if version in blocked.get(name, []) or (name in pins and pins[name] != version):
                    return False
            for name, bounds in roots.items():
                if name not in selected or not bounds[0] <= selected[name] <= bounds[1]:
                    return False

            graph = {}
            reachable = set()
            pending = list(roots)
            while pending:
                name = pending.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                if name not in selected:
                    return False
                version = selected[name]
                row = next(r for r in packages[name] if r["version"] == version)
                deps = [dep for dep in row.get("deps", [])
                        if not dep.get("feature") or dep["feature"] in features]
                graph[name] = []
                for dep in deps:
                    other = dep["name"]
                    if other not in selected or not dep["min"] <= selected[other] <= dep["max"]:
                        return False
                    graph[name].append(other)
                    if other not in reachable:
                        pending.append(other)
            if reachable != set(selected):
                return False

            active, finished = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(other) for other in graph.get(name, [])):
                    return False
                active.remove(name)
                finished.add(name)
                return True
            return all(visit(name) for name in graph)

        for assignment in product(*options):
            if valid(assignment):
                return {"versions": {name: version for name, version in zip(names, assignment)
                                     if version != -1}}
        return {"error": "unsatisfiable"}
    return solve


def _build_component_07():
    from itertools import combinations

    def feasible(chosen, data):
        ids = {job["id"] for job in chosen}
        if not set(data.get("mandatory", [])).issubset(ids):
            return False
        counts = {}
        for job in chosen:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        for group, bounds in data.get("quotas", {}).items():
            count = counts.get(group, 0)
            if not bounds[0] <= count <= bounds[1]:
                return False
        timeline = sorted((job["start"], 1, job) for job in chosen)
        # Check overlap at each distinct start; intervals are half-open.
        for time, _, _ in timeline:
            if sum(job["start"] <= time < job["end"] for job in chosen) > 2:
                return False
        return True

    def solve(data):
        k = data["k"]
        blocked = set(data.get("blocked", []))
        jobs = [job for job in data["jobs"] if job["id"] not in blocked]
        best = None
        for chosen in combinations(jobs, k):
            if not feasible(chosen, data):
                continue
            ids = tuple(sorted(job["id"] for job in chosen))
            value = sum(job["value"] for job in chosen)
            if best is None or value > best[0] or (value == best[0] and ids < best[1]):
                best = (value, ids)
        if best is None:
            return {"error": "impossible"}
        return {"selected": list(best[1]), "value": best[0]}
    return solve


def _build_component_08():
    import heapq

    def solve(data):
        required = data.get("required", [])
        full = (1 << len(required)) - 1
        def visit_mask(node):
            mask = 0
            for i, required_node in enumerate(required):
                if node == required_node:
                    mask |= 1 << i
            return mask

        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)
        source = data["source"]
        start = data["start"]
        initial = (source, visit_mask(source), data["coupons"])
        distances = {initial: start}
        queue = [(start, source, initial[1], initial[2])]
        while queue:
            time, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distances.get(state) != time:
                continue
            if node == data["target"] and mask == full:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                choices = [(edge["duration"], remaining)]
                if remaining:
                    duration = max(2, edge["duration"] - edge.get("discount", 0))
                    choices.append((duration, remaining - 1))
                for duration, left in choices:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask | visit_mask(next_node)
                    next_state = (next_node, next_mask, left)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, next_node, next_mask, left))
        return {"arrival": None}
    return solve


SOLVERS = {
    "component_01": _ledger("revision_first", "discounted"),
    "component_02": _ledger("sequence_first", "discounted"),
    "component_03": _ledger("revision_first", "original"),
    "component_04": _ledger("sequence_first", "original"),
    "component_05": _ledger("revision_first", "discounted"),
    "component_06": _build_component_06(),
    "component_07": _build_component_07(),
    "component_08": _build_component_08(),
}
